1	// Gate 3: safe-coding lint (google/safety-web) + a few CSP-compatibility rules.
2	// This file is part of the harness. The agent does not edit it (see verify.sh gate 0).
3	import tseslint from 'typescript-eslint';
4	import safetyWeb from '@safety-web/eslint-plugin';
5	
6	const SAFE_URL_HINT = 'from safevalues/dom (it rejects javascript: URLs). See harness/README.md.';
7	
8	/**
9	 * safety-web reports at two confidence levels. VIOLATION is the bar tsec (gate 2) enforces; the
10	 * *_POTENTIAL_VIOLATION level also fires on e.g. `textContent` assignments to an `HTMLElement`-typed
11	 * variable (it could, statically, be a <script>). The gate enforces the tsec bar so that both
12	 * compile-time gates agree; a potential violation is still a real finding, only not a build error here.
13	 */
14	function atViolationConfidence(rule) {
15	  return {
16	    ...rule,
17	    create(context) {
18	      // context.report is non-configurable, so shadow it on a derived object instead of proxying.
19	      const filtered = Object.create(context, {
20	        report: {
21	          value: (descriptor) => {
22	            if (descriptor?.data?.confidence === 'VIOLATION') context.report(descriptor);
23	          },
24	        },
25	      });
26	      return rule.create(filtered);
27	    },
28	  };
29	}
30	const safetyWebAtTsecBar = {
31	  rules: { 'trusted-types-checks': atViolationConfidence(safetyWeb.rules['trusted-types-checks']) },
32	};
33	
34	export default tseslint.config(
35	  {
36	    ignores: [
37	      'dist/**',
38	      'node_modules/**',
39	      'harness/server.mjs',
40	      'harness/vite.config.mjs',
41	      // The one reviewed Trusted Types boundary. Exempted in tsec-exemptions.json for the same reason.
42	      'harness/trusted-boundary.ts',
43	      '.scaffold/**',
44	    ],
45	  },
46	  {
47	    files: ['src/**/*.ts', 'harness/entry.ts'],
48	    languageOptions: {
49	      parser: tseslint.parser,
50	      parserOptions: { projectService: true, tsconfigRootDir: import.meta.dirname },
51	    },
52	    plugins: { '@safety-web': safetyWebAtTsecBar },
53	    rules: {
54	      '@safety-web/trusted-types-checks': 'error',
55	      'no-eval': 'error',
56	      'no-implied-eval': 'error',
57	      'no-new-func': 'error',
58	      'no-script-url': 'error',
59	      'no-restricted-syntax': [
60	        'error',
61	        {
62	          selector: "AssignmentExpression[left.type='MemberExpression'][left.property.name='href'][right.type!='Literal']",
63	          message: 'Assigning a non-literal to .href can inject javascript: URLs. Use setAnchorHref(anchor, url) ' + SAFE_URL_HINT,
64	        },
65	        {
66	          selector: "AssignmentExpression[left.type='MemberExpression'][left.object.name='location']",
67	          message: 'Navigating via location.* from a string can inject javascript: URLs. Use setLocationHref(location, url) ' + SAFE_URL_HINT,
68	        },
69	        {
70	          selector: "CallExpression[callee.object.name='location'][callee.property.name=/^(assign|replace)$/]",
71	          message: 'location.assign/replace from a string can inject javascript: URLs. Use locationAssign/locationReplace ' + SAFE_URL_HINT,
72	        },
73	        {
74	          selector: "CallExpression[callee.property.name='setAttribute'][arguments.0.value=/^(href|src|srcdoc|action|formaction|on[a-z]+)$/i]",
75	          message: 'setAttribute on a URL/handler attribute bypasses type checks. Use the safevalues/dom setter for that element, or a validated URL. See harness/README.md.',
76	        },
77	      ],
78	    },
79	  },
