input.content:
:root {
  color-scheme: light;
  --ink: #1b1b1f;
  --muted: #5b5b66;
  --border: #d8d8e0;
  --accent: #0f766e;
  --bg: #fafafa;
  --surface: #ffffff;
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
}

#app {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

.field {
  margin-bottom: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

input,
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  color: inherit;
}

input:focus,
textarea:focus,
button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

#note-form {
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 10px;
  padding: 1rem;
  margin-bottom: 1rem;
}

#note-form button[type='submit'] {
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 6px;
  padding: 0.55rem 1rem;
  font-weight: 600;
  cursor: pointer;
}

.search-field {
  margin-top: 0.5rem;
}

#results-line {
  min-height: 1.2rem;
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.25rem 0 1rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.note {
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 10px;
  padding: 0.9rem 1rem;
}

.note[aria-current='true'] {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent) inset;
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0 0 0.4rem;
}

.note-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.note-heading {
  margin: 0;
  font-size: 1.05rem;
}

.note-title {
  font: inherit;
  font-weight: 600;
  background: none;
  border: none;
  padding: 0;
  color: var(--accent);
  cursor: pointer;
  text-align: left;
}

.note-title:hover {
  text-decoration: underline;
}

.note-body {
  color: var(--ink);
  line-height: 1.5;
  word-wrap: break-word;
}

.note-body a {
  color: var(--accent);
}

.note-meta {
  margin: 0.4rem 0 0;
  font-size: 0.75rem;
  color: var(--muted);
}

.empty-state {
  color: var(--muted);
  padding: 1rem 0;
}

