  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.25rem 0 1rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.note {
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 10px;
  padding: 0.9rem 1rem;
}

.note[aria-current='true'] {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent) inset;
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin: 0 0 0.4rem;
}

.note-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.note-heading {
  margin: 0;
  font-size: 1.05rem;
}

.note-title {
  font: inherit;
  font-weight: 600;
  background: none;
  border: none;
  padding: 0;
  color: var(--accent);
  cursor: pointer;
  text-align: left;
}

.note-title:hover {
  text-decoration: underline;
}

.note-body {
  color: var(--ink);
  line-height: 1.5;
  word-wrap: break-word;
}

.note-body a {
  color: var(--accent);
}

.note-meta {
  margin: 0.4rem 0 0;
  font-size: 0.75rem;
  color: var(--muted);
}

.empty-state {
  color: var(--muted);
  padding: 1rem 0;
}

