import { chromium } from '@playwright/test';

const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => errors.push(String(err)));

await page.goto('http://127.0.0.1:4174/');
await page.waitForSelector('#feed .note');

const noteCount = await page.locator('#feed .note').count();
console.log('initial note count:', noteCount);

// search
await page.fill('#search', 'Douro');
await page.waitForTimeout(100);
const resultsText = await page.locator('#results-line').textContent();
console.log('results line:', JSON.stringify(resultsText));
const filteredCount = await page.locator('#feed .note').count();
console.log('filtered note count:', filteredCount);

// clear search, add a note
await page.fill('#search', '');
await page.fill('#title', 'Test note <b>bold</b>');
await page.fill('#body', 'Hello <b>world</b>, visit <a href="https://example.com">example</a>.\nSecond line.');
await page.fill('#avatar', 'https://example.com/avatar.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(100);

const newCount = await page.locator('#feed .note').count();
console.log('after add count:', newCount);
const firstArticle = page.locator('#feed .note').first();
const firstTitleHtml = await firstArticle.locator('.note-title').innerHTML();
console.log('first title html:', firstTitleHtml);
const firstBodyHtml = await firstArticle.locator('.note-body').innerHTML();
console.log('first body html:', firstBodyHtml);
const firstNoteId = await firstArticle.getAttribute('data-note-id');
console.log('first note id:', firstNoteId);

// click title to select
await firstArticle.locator('.note-title').click();
await page.waitForTimeout(100);
const hash = await page.evaluate(() => location.hash);
console.log('hash after select:', hash);
const ariaCurrent = await firstArticle.getAttribute('aria-current');
console.log('aria-current:', ariaCurrent);

// reload and check restore
await page.reload();
await page.waitForSelector('#feed .note');
const hashAfterReload = await page.evaluate(() => location.hash);
const searchValAfterReload = await page.inputValue('#search');
console.log('hash after reload:', hashAfterReload, 'search value:', searchValAfterReload);
const selectedAfterReload = await page.locator('.note[aria-current="true"]').count();
console.log('selected count after reload:', selectedAfterReload);

console.log('console/page errors:', errors);
await browser.close();

